import ast

def longestSubarray(arr, k):
    prefix_sum = 0
    max_len = 0
    first_seen = {}

    for i, num in enumerate(arr):
        prefix_sum += num

        if prefix_sum == k:
            max_len = i + 1

        if prefix_sum - k in first_seen:
            max_len = max(max_len, i - first_seen[prefix_sum - k])

        if prefix_sum not in first_seen:
            first_seen[prefix_sum] = i

    return max_len


# Read input
arr, k = ast.literal_eval(input().strip())

# Print output
print(longestSubarray(arr, k))

