import java.util.*;

public class Main {
    public static List<int[]> merge(int[][] intervals) {
        if (intervals.length <= 1) return Arrays.asList(intervals);
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));

        List<int[]> result = new ArrayList<>();
        int[] current = intervals[0];
        result.add(current);

        for (int[] interval : intervals) {
            if (interval[0] <= current[1]) {
                current[1] = Math.max(current[1], interval[1]);
            } else {
                current = interval;
                result.add(current);
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;

        String input = sc.nextLine().trim();
        // Parse input [[1,3],[2,6],[8,10],[15,18]]
        input = input.replaceAll("\\[\\[|\\]\\]", "");
        String[] pairs = input.split("\\],\\[|\\]\\s*,\\s*\\[");

        int[][] intervals = new int[pairs.length][2];
        for (int i = 0; i < pairs.length; i++) {
            String[] nums = pairs[i].trim().split(",");
            intervals[i][0] = Integer.parseInt(nums[0].trim());
            intervals[i][1] = Integer.parseInt(nums[1].trim());
        }

        List<int[]> res = merge(intervals);

        // Print in standard array format [[1,6],[8,10],[15,18]]
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < res.size(); i++) {
            sb.append("[").append(res.get(i)[0]).append(",").append(res.get(i)[1]).append("]");
            if (i < res.size() - 1) sb.append(",");
        }
        sb.append("]");
        System.out.println(sb.toString());
    }
}

